// Cross-language golden-vector runner: executes the TypeScript engine
// against vectors.json, which was generated by the Python reference
// engine. Any drift between the two implementations fails here.
// Run: node engine-tests/run.ts   (Node >= 22 type stripping)
import { readFileSync } from "node:fs";
import { computeAdditionalMedicare, computeFederalTax, computeNiit, niitBreakdown } from "../engine/federal.ts";
import { computeHouseholdTax } from "../engine/snapshot.ts";
import { computeStateTaxOnGain } from "../engine/state.ts";
import { checkWashSale } from "../engine/washSale.ts";
import { simulate } from "../engine/taximpact.ts";
import { simulateScenario } from "../engine/snapshot.ts";
import { esppDisposition, rsuVest } from "../engine/equity.ts";
import { fbarRequired, foreignTaxCredit, form8938Required } from "../engine/foreign.ts";
import { treatyPosition, withholdingCap } from "../engine/treaty.ts";
import { documentFreshness } from "../engine/freshness.ts";
import { annualFocus, documentRequests, nextAction, nextPhaseStart, payrollShortcut } from "../engine/guidance.ts";
import { classifyDocument } from "../engine/classify.ts";
import { predictionConfidence } from "../engine/confidence.ts";
import type { HouseholdIntake } from "../engine/intake.ts";

const MFJ = "married_filing_jointly";
const vectors = JSON.parse(readFileSync(new URL("./vectors.json", import.meta.url), "utf-8"));

function compute(id: string): Record<string, unknown> {
  switch (id) {
    case "federal_mfj_200k": { const r = computeFederalTax(200000, MFJ); return { total_tax: r.totalTax, taxable_income: r.taxableIncome, marginal_rate: r.marginalRate }; }
    case "federal_single_80k": { const r = computeFederalTax(80000, "single"); return { total_tax: r.totalTax }; }
    case "federal_mfj_ltcg": { const r = computeFederalTax(200000, MFJ, 50000); return { ltcg_tax: r.ltcgTax, total_tax: r.totalTax }; }
    case "niit": return { value: computeNiit(300000, 20000, MFJ) };
    // Engine round 45 - Additional Medicare (Copilot's vector set).
    // withheld figures carry the 1.45% base + the extra 0.9% over the
    // earner's $200K; expected values are hand arithmetic on IRC
    // 3101(b)(2), independent of the implementation.
    case "addmed_mfj_under_250k": { const r = computeAdditionalMedicare([120000, 80000], [1740, 1160], MFJ); return { liability: r.liability, withheld_credit: r.withheldCredit, net: r.net }; }
    case "addmed_mfj_one_over_200k": { const r = computeAdditionalMedicare([300000, 100000], [5115, 1450], MFJ); return { liability: r.liability, withheld_credit: r.withheldCredit, net: r.net }; }
    case "addmed_mfj_both_under_but_over": { const r = computeAdditionalMedicare([180000, 130000], [2610, 1885], MFJ); return { liability: r.liability, withheld_credit: r.withheldCredit, net: r.net }; }
    case "addmed_mfj_both_over_200k": { const r = computeAdditionalMedicare([250000, 250000], [4075, 4075], MFJ); return { liability: r.liability, withheld_credit: r.withheldCredit, net: r.net }; }
    case "addmed_bonus_only": { const r = computeAdditionalMedicare([255000, 50000], [4147.5, 725], MFJ); return { liability: r.liability, withheld_credit: r.withheldCredit, net: r.net }; }
    case "addmed_wages_vs_box1": { const r = computeAdditionalMedicare([320000], [5720], "single"); return { liability: r.liability, withheld_credit: r.withheldCredit, net: r.net }; }
    // Engine round 45 - NIIT base breakdown (Copilot's vector set).
    case "niit_magi_under": { const r = niitBreakdown(240000, 50000, MFJ); return { nii_subject: r.niiSubject, magi_excess: r.magiExcess, base: r.base, niit: r.niit }; }
    case "niit_nii_zero": { const r = niitBreakdown(300000, 0, MFJ); return { nii_subject: r.niiSubject, magi_excess: r.magiExcess, base: r.base, niit: r.niit }; }
    case "niit_loss_carryforward": { const r = niitBreakdown(350000, 20000, MFJ); return { nii_subject: r.niiSubject, magi_excess: r.magiExcess, base: r.base, niit: r.niit }; }
    case "niit_interest_dividends": { const r = niitBreakdown(350000, 15000, MFJ); return { nii_subject: r.niiSubject, magi_excess: r.magiExcess, base: r.base, niit: r.niit }; }
    case "niit_bound_by_excess": { const r = niitBreakdown(270000, 80000, MFJ); return { nii_subject: r.niiSubject, magi_excess: r.magiExcess, base: r.base, niit: r.niit }; }
    case "niit_bound_by_nii": { const r = niitBreakdown(400000, 10000, MFJ); return { nii_subject: r.niiSubject, magi_excess: r.magiExcess, base: r.base, niit: r.niit }; }
    // Engine round 45 - snapshot reconciliation end to end.
    case "snapshot_addmed_recon": { const r = computeHouseholdTax(MFJ, 400000, 140000, 0, 0, null, 0, 0, "AZ", [300000, 100000], [5115, 1450], 0); return { additional_medicare_liability: r.additionalMedicareLiability, additional_medicare_withheld: r.additionalMedicareWithheld, additional_medicare_net: r.additionalMedicareNet, total_federal_liability: r.totalFederalLiability, total_federal_payments: r.totalFederalPayments, federal_refund_owe: r.federalRefundOwe, medicare_included: r.medicareIncluded }; }
    case "az_gain": return { tax: computeStateTaxOnGain(10000, "AZ").tax };
    case "wash_sale": { const w = checkWashSale("AAPL", "2026-03-15", -20, 50, [{ ticker: "AAPL", broker: "Fidelity", quantity: 40, purchaseDate: "2026-03-25", costBasisPerShare: 150 }]); return { triggered: w.triggered, disallowed_loss: w.disallowedLoss, adjusted_basis_per_share: w.adjustedBasisPerShare }; }
    case "taximpact_st": { const s = simulate({ ticker: "XYZ", broker: "Fidelity", quantity: 100, costBasisPerShare: 50, salePricePerShare: 80, purchaseDate: "2025-06-01", saleDate: "2026-01-15" }, { filingStatus: MFJ, taxYear: 2026, state: "AZ", estimatedOrdinaryIncome: 150000 }); return { total_tax_impact: s.impact.totalTaxImpact, savings_by_waiting: s.timing?.taxSavingsByWaiting, days_until_long_term: s.timing?.daysUntilLongTerm }; }
    case "taximpact_carryforward": { const s = simulate({ ticker: "XYZ", broker: "Fidelity", quantity: 100, costBasisPerShare: 50, salePricePerShare: 80, purchaseDate: "2025-06-01", saleDate: "2026-01-15" }, { filingStatus: MFJ, taxYear: 2026, state: "AZ", estimatedOrdinaryIncome: 150000, capitalLossCarryforward: 1000 }); return { losses_applied: s.impact.lossesApplied, adjusted_gain: s.adjustedGain }; }
    case "scenario_withholding": return simulateScenario({ filingStatus: MFJ, baseIncome: 180000, federalWithholdingYtd: 25000, stateWithholdingYtd: 4000, action: "change_withholding", deltaAmount: 2000 }) as Record<string, unknown>;
    case "rsu_vest": { const r = rsuVest(1000, 50, "2026-03-01", MFJ, 200000); return { ordinary_income: r.ordinaryIncome, federal_withheld: r.federalWithheld, projected_gap: r.projectedGap }; }
    case "espp_disqual": { const e = esppDisposition(100, "2024-01-01", 40, "2024-07-01", 50, 34, "2025-03-01", 60); return { ordinary_income_total: e.ordinaryIncomeTotal, capital_gain_total: e.capitalGainTotal, capital_is_long_term: e.capitalIsLongTerm }; }
    case "espp_qual": { const e = esppDisposition(100, "2023-01-01", 40, "2023-07-01", 50, 34, "2025-08-01", 60); return { ordinary_income_total: e.ordinaryIncomeTotal, capital_gain_total: e.capitalGainTotal }; }
    case "fbar": return { required: fbarRequired([6000, 5000]).required };
    case "f8938": return { required: form8938Required(120000, 130000, MFJ).required };
    case "ftc": { const f = foreignTaxCredit(5000, 20000, 167800, 26340); return { credit_allowed: f.creditAllowed, excess_credit: f.excessCredit }; }
    case "treaty_div": return { rate: withholdingCap("dividends", { corporate10pct: true }).treatyCapRate };
    case "treaty_ss": return { overrides: treatyPosition("social_security_benefits", true).savingClauseOverrides };
    case "freshness_payslip_stale": { const f = documentFreshness({ docType: "payslip", status: "parsed", confidence: 0.9, capturedOn: "2026-10-01" }, "2026-11-07"); return { status: f.status, age_days: f.ageDays }; }
    case "confidence_perfect": { const h: HouseholdIntake = { name: "T", state: "AZ", filingStatus: MFJ, members: [{ name: "A", role: "adult" }], documents: ["payslip", "prior_return", "w2", "401k_statement", "hsa_statement", "529_statement", "brokerage_statement"].map((t) => ({ docType: t, status: "parsed", confidence: 1, capturedOn: "2026-11-07" })), calibration: { taxYear: 2025, federalFiled: true, stateFiled: true, actualFederalRefundOwe: 2400, actualStateRefundOwe: 1100, outcomeVerified: true } }; return { score: predictionConfidence(h, "2026-11-07").score }; }
    case "confidence_stale": { const h: HouseholdIntake = { name: "T", state: "AZ", filingStatus: MFJ, members: [{ name: "A", role: "adult" }], documents: [{ docType: "payslip", status: "parsed", confidence: 0.9, capturedOn: "2026-10-01" }] }; return { score: predictionConfidence(h, "2026-11-07").score }; }
    case "confidence_empty": { const h: HouseholdIntake = { name: "T", state: "AZ", filingStatus: MFJ, members: [{ name: "A", role: "adult" }], documents: [] }; return { score: predictionConfidence(h, "2026-11-07").score }; }
    case "guidance_requests_minimal": { const h: HouseholdIntake = { name: "T", state: "AZ", filingStatus: MFJ, members: [{ name: "A", role: "adult", payFrequency: "biweekly" }], documents: [] }; const r = documentRequests(h, {}, "2026-11-07"); return { count: r.length, first_key: r[0].key, payslip_status: r.find((x) => x.key === "payslip")?.status }; }
    case "guidance_requests_full": { const h: HouseholdIntake = { name: "T", state: "AZ", filingStatus: MFJ, members: [{ name: "A", role: "adult" }], documents: [], hasRsu: true }; const r = documentRequests(h, { hasHsa: true, hasBrokerage: true, hasRental: true, hasCollegeStudent: true }, "2026-11-07"); return { count: r.length }; }
    case "guidance_shortcut_ok": { const r = payrollShortcut("no", "no", "no", 0); return { provisional: r.provisional, consecutive_after: r.consecutiveAfter }; }
    case "guidance_shortcut_due": { const r = payrollShortcut("no", "no", "no", 2); return { needs_document: r.needsDocument }; }
    case "guidance_shortcut_changed": { const r = payrollShortcut("yes", "no", "no", 0); return { needs_document: r.needsDocument, consecutive_after: r.consecutiveAfter }; }
    case "guidance_annual_nov": return { key: annualFocus(11).key };
    case "classify_w2": { const c = classifyDocument(["Wages, tips, other compensation", "Social security wages", "Medicare wages and tips", "Federal income tax withheld"].map((k) => ({ key: k, value: "1", confidence: 0.9 }))); return { doc_type: c.docType, level: c.level, score: c.score }; }
    case "classify_payslip": { const c = classifyDocument(["Gross pay", "Federal income tax", "State income tax", "Year to date"].map((k) => ({ key: k, value: "1", confidence: 0.9 }))); return { doc_type: c.docType, level: c.level, score: c.score }; }
    case "classify_1099b": { const c = classifyDocument(["Proceeds", "Cost or other basis", "Gain or loss"].map((k) => ({ key: k, value: "1", confidence: 0.9 }))); return { doc_type: c.docType, level: c.level, score: c.score }; }
    case "classify_prior_return": { const c = classifyDocument(["Adjusted gross income", "Taxable income", "Total tax"].map((k) => ({ key: k, value: "1", confidence: 0.9 })), "Form 1040 U.S. Individual Income Tax Return\nAdjusted gross income 185,000\nTaxable income 152,800\nTotal tax 24,310"); return { doc_type: c.docType, level: c.level, score: c.score }; }
    case "classify_401k": { const c = classifyDocument(["Ending balance", "Vested balance", "Employee contributions", "Employer contributions"].map((k) => ({ key: k, value: "1", confidence: 0.9 }))); return { doc_type: c.docType, level: c.level, score: c.score }; }
    case "classify_unknown": { const c = classifyDocument(["Banana bread recipe", "Preheat oven"].map((k) => ({ key: k, value: "1", confidence: 0.9 }))); return { doc_type: c.docType, level: c.level, score: c.score }; }
    case "guidance_annual_jun": return { key: annualFocus(6).key };
    case "guidance_next_phase_wrap": { const n = nextPhaseStart(12); return { month: n.month, title: n.title }; }
    case "guidance_action_calibration": { const a = nextAction({ calibrationMissing: true, verificationDue: false, confidenceBand: "High", confidenceScore: 85 }); return { confidence: a.confidence, has_return: a.action.includes("filed return") }; }
    case "guidance_action_below": { const a = nextAction({ calibrationMissing: false, verificationDue: false, federalPosition: "below", federalDelta: 1234, confidenceBand: "Moderate", confidenceScore: 60 }); return { why_has_amount: a.why.includes("$1,234") }; }
    default: throw new Error(`unknown vector ${id}`);
  }
}

let passed = 0;
let failed = 0;
for (const v of vectors) {
  const got = compute(v.id);
  const diffs: string[] = [];
  for (const [key, expected] of Object.entries(v.expect)) {
    const actual = got[key];
    const ok = typeof expected === "number" && typeof actual === "number"
      ? Math.abs(actual - expected) <= 0.011
      : actual === expected;
    if (!ok) diffs.push(`${key}: expected ${expected}, got ${actual}`);
  }
  if (diffs.length) { failed++; console.log(`FAIL ${v.id} - ${diffs.join("; ")}`); }
  else { passed++; console.log(`PASS ${v.id}`); }
}
console.log(`\n${passed}/${vectors.length} vectors match the Python reference engine`);
if (failed) process.exit(1);
